package connect

import (
	"errors"
)

// ResultOf computes the winner of a Hex / Polygon game.
//
// Each line of the board is a row of the parallelogram. The test harness
// strips every space before calling us, so each row holds the same number of
// cells (cols) and the board is a full rows x cols grid of hexagons.
//
// Player X connects the left side to the right side; player O connects the
// top side to the bottom side. The first player to bridge their two sides wins.
func ResultOf(lines []string) (string, error) {
	rows := len(lines)
	if rows == 0 {
		return "", nil
	}
	cols := len(lines[0])
	for _, line := range lines {
		if len(line) != cols {
			return "", errors.New("malformed board: every row must have the same length")
		}
	}

	// The six edge-sharing neighbors of a hex cell (i, j). Each row is shifted
	// right by one, so a cell's lower neighbors are (i+1, j-1) and (i+1, j),
	// and its upper neighbors are (i-1, j) and (i-1, j+1).
	var deltas = [][2]int{{0, -1}, {0, 1}, {-1, 0}, {-1, 1}, {1, -1}, {1, 0}}

	// connected reports whether the player has a chain of stones from any start
	// cell to any cell satisfying goal.
	connected := func(player byte, starts [][2]int, goal func(i, j int) bool) bool {
		seen := make([][]bool, rows)
		for i := range seen {
			seen[i] = make([]bool, cols)
		}
		queue := make([][2]int, 0, len(starts))
		for _, s := range starts {
			if lines[s[0]][s[1]] == player {
				seen[s[0]][s[1]] = true
				queue = append(queue, s)
			}
		}
		for len(queue) > 0 {
			cell := queue[0]
			queue = queue[1:]
			i, j := cell[0], cell[1]
			if goal(i, j) {
				return true
			}
			for _, d := range deltas {
				x, y := i+d[0], j+d[1]
				if x < 0 || y < 0 || x >= rows || y >= cols || seen[x][y] || lines[x][y] != player {
					continue
				}
				seen[x][y] = true
				queue = append(queue, [2]int{x, y})
			}
		}
		return false
	}

	// X connects the left side to the right side.
	xStarts := make([][2]int, rows)
	for i := 0; i < rows; i++ {
		xStarts[i] = [2]int{i, 0}
	}
	if connected('X', xStarts, func(_, j int) bool { return j == cols-1 }) {
		return "X", nil
	}

	// O connects the top side to the bottom side.
	oStarts := make([][2]int, cols)
	for j := 0; j < cols; j++ {
		oStarts[j] = [2]int{0, j}
	}
	if connected('O', oStarts, func(i, _ int) bool { return i == rows-1 }) {
		return "O", nil
	}

	return "", nil
}
